// Convierte la nota de voz en un mensaje de texto normal,
// para que el resto del flujo no note la diferencia.
const update = $('01 - Recibe Mensaje Telegram').item.json;
const r = $json;
const transcripcion = String(
  r?.content?.parts?.[0]?.text ??
  r?.candidates?.[0]?.content?.parts?.[0]?.text ??
  r?.text ?? ''
).trim();

return {
  json: {
    ...update,
    message: { ...update.message, text: transcripcion },
    es_voz: true
  }
};

const datos = $('01b - Normaliza Entrada Telegram').item.json;
const texto = datos.texto_o_callback || '';
const patron = /^(\S+@\S+\.\S+)\s+(.+)$/;
const match = texto.match(patron);

if (match) {
  return {
    json: {
      es_login: true,
      email: match[1].trim(),
      password: match[2].trim(),
      chat_id: datos.chat_id
    }
  };
} else {
  return {
    json: {
      es_login: false,
      chat_id: datos.chat_id
    }
  };
}

const update = $input.item.json;
const esCallback = update.callback_query !== undefined;

if (esCallback) {
  return {
    json: {
      es_callback: true,
      chat_id: update.callback_query.message.chat.id.toString(),
      texto_o_callback: update.callback_query.data,
      callback_query_id: update.callback_query.id,
      message_id: update.callback_query.message.message_id,
      file_id: null,
      es_archivo: false
    }
  };
} else {
  const msg = update.message;
  let file_id = null;
  let es_archivo = false;

  if (msg.photo && msg.photo.length > 0) {
    file_id = msg.photo[msg.photo.length - 1].file_id;
    es_archivo = true;
  } else if (msg.document) {
    file_id = msg.document.file_id;
    es_archivo = true;
  }

  return {
    json: {
      es_callback: false,
      chat_id: msg.chat.id.toString(),
      texto_o_callback: msg.text || '',
      callback_query_id: null,
      message_id: msg.message_id,
      file_id: file_id,
      es_archivo: es_archivo
    }
  };
}
